PROGRAM ST110_PLOCK_FRAN_BAND
VAR
    fbTrack   : CONVEYOR_TRACK_FB;
    rGripX    : REAL;
    xPickReq  : BOOL;
END_VAR

fbTrack(EN := ST110_CAM_FOUND,
        POS_IN := ST110_ENC_POS,
        SPEED := ST110_CNV_SPD,
        POS_OUT => rGripX);

xPickReq := ST110_CAM_FOUND AND ST110_VAC_OK;

ST110_CAM_TRIG := NOT ST110_RB_BUSY;
ST110_VAC_ON   := xPickReq;
ST110_RB_PICK  := xPickReq AND NOT ST110_RB_BUSY;
END_PROGRAM
